def test_exception_propagation():
    class MockClient:
        def __init__(self):
            pass
        def get(self, url, timeout=None):
            if timeout != 30:
                raise RuntimeError('timeout mismatch')
            return 'ok'

    client = MockClient()
    # if client raises, it should propagate
    try:
        fetch(client, 'http://example.com')
    except RuntimeError as e:
        pass  # expected if bug, but not
    # call with a failing get
    class BadClient:
        def get(self, url, timeout=None):
            raise ValueError('network error')
    bad = BadClient()
    try:
        fetch(bad, 'http://example.com')
    except ValueError:
        pass  # exception propagated correctly
    else:
        assert False, 'exception not propagated'

if __name__ == '__main__':
    test_fetch_signature()
    test_fetch_custom_timeout()
    test_exception_propagation()
    print('All tests passed')
